  assert.equal(r.value.subtotal, 100000000);
  assert.equal(r.value.vat, 21000000);
  assert.equal(r.value.total, 121000000);
});

test('invoiceTotals bulk discount with 10+ units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 50000
  // discount1 = 0 (no line discount)
  // bulk discount = (50000 - 0) * 2.5% = 1250
  // total discount = 1250
  // after discount = 48750
  // vat = 48750 * 21% = 10237.5 rounded to 10238
  assert.equal(r.value.subtotal, 50000);
  assert.equal(r.value.discount, 1250);
  assert.equal(r.value.vat, 10238);
  assert.equal(r.value.total, 58988);
});

test('invoiceTotals no bulk discount with 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 45000
  // discount1 = 0
  // bulk discount = 0 (qty < 10)
  // total discount = 0
  // vat = 45000 * 21% = 9450
  assert.equal(r.value.subtotal, 45000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 9450);
  assert.equal(r.value.total, 54450);
});

test('invoiceTotals bulk discount after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 50000
  // discount1 = 50000 * 10% = 5000
  // remaining1 = 45000
  // bulk discount = 45000 * 2.5% = 1125
  // total discount = 5000 + 1125 = 6125
  // after discount = 43875
  // vat = 43875 * 21% = 9213.75 rounded to 9214
  assert.equal(r.value.subtotal, 50000);
  assert.equal(r.value.discount, 6125);
  assert.equal(r.value.vat, 9214);
  assert.equal(r.value.total, 52964);
});

test('invoiceTotals bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 50000, discount = 1250 (bulk), after = 48750, vat = 10238
  // Line 2: 25000, no bulk discount, vat = 5250
  // Total subtotal = 75000
  // Total discount = 1250
  // Total vat = 15488
  assert.equal(r.value.subtotal, 75000);
  assert.equal(r.value.discount, 1250);
  assert.equal(r.value.vat, 15488);
  assert.equal(r.value.total, 89238);
});

test('invoiceTotals bulk discount exactly 10 units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 10000
  // bulk discount = 10000 * 2.5% = 250
  assert.equal(r.value.discount, 250);
});

test('invoiceTotals no bulk discount at 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 9000
  // no bulk discount
  assert.equal(r.value.discount, 0);
});

test('invoiceTotals bulk discount with high line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 50, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // lineTotal = 100000
  // discount1 = 100000 * 50% = 50000
  // remaining1 = 50000
  // bulk discount = 50000 * 2.5% = 1250
  // total discount = 51250
  // after discount = 48750
  // vat = 48750 * 21% = 10237.5 rounded to 10238
  assert.equal(r.value.subtotal, 100000);
  assert.equal(r.value.discount, 51250);
  assert.equal(r.value.vat, 10238);
  assert.equal(r.value.total, 58988);
});

test('invoiceTotals bulk discount applied to all eligible lines', () => {
  const invoice = {
    lines: [
      { qty: 15, unitPrice: 2000, discountPercent: 0, vatRate: 0 },
      { qty: 20, unitPrice: 3000, discountPercent: 5, vatRate: 0 },
      { qty: 5, unitPrice: 4000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 30000, bulk = 750, discount = 750
  // Line 2: 60000, discount1 = 3000, remaining = 57000, bulk = 1425, discount = 4425
  // Line 3: 20000, no bulk discount = 0
  // Total discount = 750 + 4425 + 0 = 5175
  assert.equal(r.value.subtotal, 110000);
  assert.equal(r.value.discount, 5175);
});

