test('lateFee fee is proportional to amount due', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  const fee1 = lateFee(issued1.value, '2026-11-10');
  const fee2 = lateFee(issued2.value, '2026-11-10');

  assert.equal(fee1.ok, true);
  assert.equal(fee2.ok, true);

