test('invoiceTotals with different VAT rates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 9, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  const line1Total = 9 * 9500; // 85500, VAT 21% = 17955
  const line2Total = 100 * 37; // 3700, VAT 9% = 333
  const line3Total = 1 * 60000; // 60000, VAT 0% = 0
  const expectedVat = Math.round(line1Total * 21 / 100) + Math.round(line2Total * 9 / 100) + 0;
  assert.equal(r.value.vat, expectedVat);
});

