});

test('applyVoucher returns VOUCHER_EXISTS if voucher already applied', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  const first = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 10000 });
  assert.equal(first.ok, true);

  const second = applyVoucher(first.value, { code: 'SAVE20', amount: 20000 });
  assert.deepEqual(second, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher returns AMOUNT_INVALID for invalid amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  const cases = [
    { amount: 0, desc: 'zero' },
    { amount: -1000, desc: 'negative' },
    { amount: 123.45, desc: 'fractional' },
    { amount: '10000', desc: 'string' },
  ];

  for (const { amount, desc } of cases) {
    assert.deepEqual(
      applyVoucher(invoiceResult.value, { code: 'SAVE10', amount }),
      { ok: false, error: 'AMOUNT_INVALID' },
      `should reject: ${desc}`
    );
  }
});

