test('invoiceTotals includes voucher in calculations', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });
  assert.equal(invoiceResult.ok, true);

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SAVE10', amount: 50000 });
  assert.equal(voucherResult.ok, true);

  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.ok, true);
  assert.equal(totals.value.voucher, 50000);
  assert.equal(totals.value.total, totals.value.subtotal + totals.value.vat - 50000);
});

